"""PD-only, explicit per-frame teaching landmarks reviewed against source slices.
Base source JSON/labels are never rewritten. No coordinate propagation between planes.
All added landmarks are approximate: expected region/attachment, not proven fibres.
"""
import json,copy,hashlib
from pathlib import Path
R=Path(__file__).resolve().parents[1]; A=R/'app/src/main/assets'; report=[]
def read(p):return json.loads(p.read_text())
LIMIT='≈, контурная точка и пунктир — ориентировочная область ожидаемого хода или прикрепления, а не доказанная визуализация отдельного пучка. Разметка учебная; тонкие компоненты могут сливаться с капсулой. Не использовать точку для оценки целости связки. Независимая врачебная верификация не выполнена.'
class Overlay:
 def __init__(self,mod,base=None):
  self.mod=mod;self.d=read(A/(mod+'-data.json'));self.l=read(A/(mod+'-labels.json'));self.series={s['sourceSeries']:s for s in self.d['series'] if '_dp' in s['id']}
  self.e=copy.deepcopy(read(A/base)) if base else {'filters':[],'structureNotes':{},'displayNames':{},'shortNames':{},'catalogNames':{},'guideChapters':[],'sources':[],'limitations':[],'seriesSlices':{s['id']:{f['annotation']:{'points':[],'regions':[],'suppress':[]} for f in s['frames']} for s in self.series.values()}}
  self.e['revision']='1.46';self.e['limitations'].insert(0,LIMIT);self.defs={};self.added=[]
 def define(self,id,name,group,note):
  self.defs[id]=(name,group);self.e['catalogNames'][str(id)]=name;self.e['structureNotes'][str(id)]=note+' '+LIMIT
 def points(self,id,se,rows):
  name,group=self.defs[id];s=self.series[se]
  for n,x,y in rows:
   f=s['frames'][n-1];a=self.e['seriesSlices'][s['id']][f['annotation']]
   a['points']=[p for p in a['points'] if p['structure']!=id]
   # Hide the previous source landmark for the same component only on the edited PD frame.
   if any(p['structure']==id for p in self.l['slices'][f['annotation']]['points']) and id not in a['suppress']:a['suppress'].append(id)
   p={'id':146000000+len(self.added),'structure':id,'name':'≈ '+name+' · ориентировочно','shortName':'≈ '+name,'filter':group,'x':x,'y':y,'category':'cartilage' if id in (912703,146110) else 'ligaments','approximate':True,'provenance':'manual-pd-topography-1.46'}
   a['points'].append(p);self.added.append({'series':s['id'],'frame':n,'annotation':f['annotation'],'imageSha256':f['sha256'],**p})
 def finish(self):
  for ss in self.e['seriesSlices'].values():
   for a in ss.values():
    a['points'].sort(key=lambda p:p['structure']);a['suppress']=sorted(set(a['suppress']))
  (A/(self.mod+'-anatomy146.json')).write_text(json.dumps(self.e,ensure_ascii=False,separators=(',',':'))+'\n')
  source_ids={p['structure'] for sl in self.l['slices'].values() for p in sl['points'] if p['filter'] in ([1194] if self.mod=='elbow-mri' else [1259,91301,91302,91303,91304,91311,91312,91313,91314,91315] if self.mod=='wrist-mri' else [1229])}
  wanted=source_ids|set(self.defs);coverage={}
  for id in sorted(wanted):
   planes={}
   for se,s in self.series.items():
    hits=[]
    for n,f in enumerate(s['frames'],1):
     extra=self.e['seriesSlices'][s['id']][f['annotation']];pts=[p for p in self.l['slices'][f['annotation']]['points'] if p['structure'] not in extra['suppress']]+extra['points']
     if any(p['structure']==id for p in pts):hits.append(n)
    planes[s['plane']]=hits
   coverage[str(id)]=planes
  report.append({'module':self.mod,'sourceDataSha256':hashlib.sha256((A/(self.mod+'-data.json')).read_bytes()).hexdigest(),'sourceLabelsSha256':hashlib.sha256((A/(self.mod+'-labels.json')).read_bytes()).hexdigest(),'added':self.added,'coverage':coverage})
